/**
 * Migration script to create employee records for users who don't have them
 * 
 * This script finds all users (except main_admin) who don't have an employee record
 * and creates one with auto-generated employee ID and proper defaults.
 * 
 * Usage: node scripts/fix-missing-employee-records.js
 */

import mongoose from 'mongoose';
import User from '../models/User.js';
import Employee from '../models/Employee.js';
import dotenv from 'dotenv';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

dotenv.config({ path: path.join(__dirname, '../.env') });

const fixMissingEmployeeRecords = async () => {
  try {
    await mongoose.connect(process.env.MONGO_URI || process.env.MONGODB_URI, {
      useNewUrlParser: true,
      useUnifiedTopology: true,
    });
    console.log('✅ MongoDB Connected\n');

    // Find all active users who don't have an employee record
    const users = await User.find({ 
      isActive: { $ne: false },
      role: { $ne: 'main_admin' } 
    });

    console.log(`📋 Found ${users.length} active users (excluding main_admin)\n`);

    let created = 0;
    let skipped = 0;
    let errors = 0;

    for (const user of users) {
      try {
        // Check if employee record already exists
        const existingEmployee = await Employee.findOne({ userId: user._id });
        
        if (existingEmployee) {
          // Check if employeeId is missing
          if (!existingEmployee.employeeId) {
            console.log(`⚠️  Employee record exists but missing employeeId for: ${user.name}`);
            
            // Find a unique employee ID that doesn't exist yet
            let nextNumber = 1;
            let employeeId;
            let isUnique = false;
            let attempts = 0;
            const maxAttempts = 1000; // Safety limit
            
            while (!isUnique && attempts < maxAttempts) {
              employeeId = `EMP${String(nextNumber).padStart(5, '0')}`;
              const exists = await Employee.findOne({ employeeId });
              if (!exists) {
                isUnique = true;
              } else {
                nextNumber++;
                attempts++;
              }
            }
            
            if (!isUnique) {
              console.error(`❌ Could not find unique employeeId after ${maxAttempts} attempts for ${user.name}`);
              errors++;
              continue;
            }
            
            existingEmployee.employeeId = employeeId;
            await existingEmployee.save();
            console.log(`✅ Fixed employeeId for ${user.name}: ${existingEmployee.employeeId}`);
            created++;
          } else {
            console.log(`⏭️  Skipped ${user.name} - Employee record already exists (${existingEmployee.employeeId})`);
            skipped++;
          }
          continue;
        }

        // Normalize phone number
        let phoneNumber = user.phone || '0000000000';
        if (phoneNumber.length !== 10 || !/^\d+$/.test(phoneNumber)) {
          phoneNumber = '0000000000';
        }

        // Map role to designation
        const roleToDesignation = {
          'admin': 'admin',
          'supervisor': 'supervisor',
          'engineer': 'engineer',
          'worker': 'worker',
          'technician': 'technician',
          'manager': 'manager',
          'helper': 'helper',
          'driver': 'driver',
          'employee': 'worker'
        };

        const designation = roleToDesignation[user.role] || 'other';
        const employeeRole = roleToDesignation[user.role] || 'worker';

        // Create employee record (employeeId will be auto-generated by pre-validate hook)
        const employee = await Employee.create({
          userId: user._id,
          name: user.name,
          phone: phoneNumber,
          email: user.email,
          designation: designation,
          role: employeeRole,
          joiningDate: user.createdAt || new Date(),
          basicSalary: 0,
          employmentType: 'full_time',
          department: 'other',
          allowances: {
            hra: 0,
            transport: 0,
            other: 0
          },
          deductions: {
            pf: 0,
            esi: 0,
            tax: 0,
            other: 0
          },
          createdBy: user.createdBy || user._id
        });

        console.log(`✅ Created employee record for ${user.name} (${employee.employeeId})`);
        created++;

      } catch (error) {
        console.error(`❌ Error processing ${user.name}:`, error.message);
        errors++;
      }
    }

    console.log(`\n📊 Summary:`);
    console.log(`   ✅ Created/Fixed: ${created}`);
    console.log(`   ⏭️  Skipped: ${skipped}`);
    console.log(`   ❌ Errors: ${errors}`);
    console.log(`   📝 Total: ${users.length}`);

    console.log('\n✨ Migration completed!');

    await mongoose.connection.close();
    process.exit(0);
  } catch (error) {
    console.error('❌ Error running migration:', error);
    await mongoose.connection.close();
    process.exit(1);
  }
};

fixMissingEmployeeRecords();

